import{_ as d,o as a,c as e,a4 as r}from"./chunks/framework.BybBnFXO.js";const m=JSON.parse('{"title":"同色宝石判别","description":"","frontmatter":{"title":"同色宝石判别","identification":"same-color-gems"},"headers":[],"relativePath":"zh/identification/same-color-gems.md","filePath":"zh/identification/same-color-gems.md","lastUpdated":1785929908000}'),o={name:"zh/identification/same-color-gems.md"};function i(h,t,l,n,s,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="同色宝石判别" tabindex="-1">同色宝石判别 <a class="header-anchor" href="#同色宝石判别" aria-label="Permalink to &quot;同色宝石判别&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>同一种颜色可能对应多种宝石——红色可能是红宝石、尖晶石、石榴石或玻璃。 结合 RI / SG / 多色性 / 包裹体，可把同色宝石逐一排除。以下流程图 覆盖红色、蓝色、绿色三大最易混淆家族。</p><h2 id="鉴定步骤" tabindex="-1">鉴定步骤 <a class="header-anchor" href="#鉴定步骤" aria-label="Permalink to &quot;鉴定步骤&quot;">​</a></h2><p><strong>1. 用折射仪测量折射率（RI）</strong></p><table tabindex="0"><thead><tr><th>RI 读数</th><th>可能家族</th><th>下一步</th></tr></thead><tbody><tr><td>1.76</td><td>刚玉（红宝石/蓝宝石）</td><td>第 2 步</td></tr><tr><td>1.71–1.72</td><td>尖晶石</td><td>✅ 判定</td></tr><tr><td>1.74–1.89</td><td>石榴石</td><td>✅ 判定</td></tr><tr><td>1.5–1.7，玻璃感</td><td>疑似玻璃</td><td>第 3 步</td></tr></tbody></table><p><strong>2. 对刚玉检测紫外荧光（LW 紫外灯）</strong></p><table tabindex="0"><thead><tr><th>荧光</th><th>结论</th></tr></thead><tbody><tr><td>强红</td><td>红宝石</td></tr><tr><td>弱或无</td><td>需光谱仪确认</td></tr></tbody></table><p><strong>3. 对疑似玻璃观察气泡 / 旋涡纹</strong></p><table tabindex="0"><thead><tr><th>观察</th><th>结论</th></tr></thead><tbody><tr><td>有气泡或流动纹</td><td>玻璃仿品</td></tr><tr><td>无</td><td>复查折射仪读数</td></tr></tbody></table><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>红：红宝石 RI 1.76 + 强红荧光；尖晶石 1.71–1.72 无荧光；石榴石 1.74–1.89。</li><li>蓝：蓝宝石 1.76 无多色性二色；坦桑石 1.69–1.70 强三色性；堇青石 1.54 三色性极强。</li><li>绿：祖母绿 1.57–1.58（浸油裂隙）；翠榴石 1.89 高色散；橄榄石 1.65–1.69（双影）。</li><li>荧光是筛分关键：天然红宝石 LW 强红，合成焰熔法常更强且带白色调。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>数值</th><th>备注</th></tr></thead><tbody><tr><td>ruby</td><td>RI 1.76 + red fluor.</td><td>—</td></tr><tr><td>sapphire</td><td>RI 1.76, no pleochroism</td><td>—</td></tr><tr><td>emerald</td><td>RI 1.57 + oil fissures</td><td>—</td></tr></tbody></table><p><em>详见<a href="./intro.html">鉴定总览</a>。</em></p>',15)])])}const p=d(o,[["render",i]]);export{m as __pageData,p as default};
